<?php
$chillerDvl = is_array($dvl_arr ?? null) ? $dvl_arr : array();
$chillerRgl = json_decode((string)@file_get_contents(__DIR__ . '/config/rgl.json'), true);
if (!is_array($chillerRgl)) $chillerRgl = array();
$diffPressureUnit = '';
$diffPressureModel = (string)($chillerDvl['BTUF6101']['model'] ?? 'bac_btu');
foreach (($chillerRgl[$diffPressureModel] ?? array()) as $registerBank) {
    if (!is_array($registerBank)) continue;
    foreach ($registerBank as $registerConfig) {
        if (is_array($registerConfig) && ($registerConfig['name'] ?? '') === 'diffpressure_lastahu') {
            $diffPressureUnit = trim((string)($registerConfig['unit'] ?? ''));
            break 2;
        }
    }
}
$chillerDetail = isset($detail_rgl_txt) ? json_decode((string)$detail_rgl_txt, true) : array();
if (!is_array($chillerDetail)) $chillerDetail = array();
$chillerTemplateConfig = json_decode((string)@file_get_contents(__DIR__ . '/config/dashboard_template.json'), true);
$mainPowerMeters = is_array($chillerTemplateConfig) ? ($chillerTemplateConfig['settings']['chiller_diagram']['main_power_meters'] ?? ($chillerTemplateConfig['settings']['chiller_diagram']['main_power_meter'] ?? array())) : array();
if (!is_array($mainPowerMeters)) $mainPowerMeters = $mainPowerMeters === '' ? array() : array((string)$mainPowerMeters);
$chillerMeterMap = is_array($chillerTemplateConfig) && is_array($chillerTemplateConfig['settings']['chiller_diagram']['chiller_meters'] ?? null) ? $chillerTemplateConfig['settings']['chiller_diagram']['chiller_meters'] : array();
$plantPowerMeterMap = is_array($chillerTemplateConfig) && is_array($chillerTemplateConfig['settings']['chiller_diagram']['plant_power_meters'] ?? null) ? $chillerTemplateConfig['settings']['chiller_diagram']['plant_power_meters'] : array();
$chwpPowerMeterMap = is_array($chillerTemplateConfig) && is_array($chillerTemplateConfig['settings']['chiller_diagram']['chwp_power_meters'] ?? null) ? $chillerTemplateConfig['settings']['chiller_diagram']['chwp_power_meters'] : array();
$chillerPmChoices = array();
foreach ($chillerDvl as $pmId=>$pmDevice) if (is_array($pmDevice)) {$pmModel=(string)($pmDevice['model']??'');if(strtoupper(trim((string)($chillerDetail[$pmModel]['abbr']??'')))==='PM')$chillerPmChoices[(string)$pmId]=(string)($pmDevice['name']??$pmId);}
$chillerAcChoices = array();
foreach ($chillerDvl as $acId=>$acDevice) if (is_array($acDevice)) {$acModel=(string)($acDevice['model']??'');if(strtoupper(trim((string)($chillerDetail[$acModel]['abbr']??'')))==='AC')$chillerAcChoices[(string)$acId]=(string)($acDevice['name']??$acId);}
$zoneAcChoices = array();
foreach ($chillerDvl as $acId=>$acDevice) if (is_array($acDevice) && preg_match('/^AC(?!H)/i', (string)$acId)) $zoneAcChoices[(string)$acId]=(string)($acDevice['name']??$acId);
$selectedChillerDevices = $chillerTemplateConfig['settings']['chiller_diagram']['chiller_devices'] ?? array_keys($chillerAcChoices);
if (!is_array($selectedChillerDevices)) $selectedChillerDevices = array((string)$selectedChillerDevices);
$chillerLoadChoices = array();
foreach ($chillerDvl as $loadId=>$loadDevice) if (is_array($loadDevice)) {$loadText=strtolower($loadId.' '.($loadDevice['name']??'').' '.($loadDevice['model']??''));if(preg_match('/btu|load/',$loadText))$chillerLoadChoices[(string)$loadId]=(string)($loadDevice['name']??$loadId);}
$selectedLoadDevices = $chillerTemplateConfig['settings']['chiller_diagram']['load_devices'] ?? array_keys($chillerLoadChoices);
if (!is_array($selectedLoadDevices)) $selectedLoadDevices = array((string)$selectedLoadDevices);
$loadZones = $chillerTemplateConfig['settings']['chiller_diagram']['load_zones'] ?? array();
if (!is_array($loadZones)) $loadZones = array();
$floorplanPoints = $chillerTemplateConfig['settings']['chiller_diagram']['floorplan_points'] ?? array();
if (!is_array($floorplanPoints)) $floorplanPoints = array();
$floorplanLayouts = $chillerTemplateConfig['settings']['chiller_diagram']['floorplan_layouts'] ?? array();
if (!is_array($floorplanLayouts)) $floorplanLayouts = array();
$cleanLoadZones = array();
$assignedAcDevices = array();
foreach ($loadZones as $loadMeter=>$zone) {
    if (!is_array($zone)) continue;
    $loadMeter = (string)$loadMeter;
    if (!isset($chillerLoadChoices[$loadMeter])) continue;
    $zoneName = trim((string)($zone['name'] ?? ''));
    $zoneDevices = is_array($zone['devices'] ?? null) ? $zone['devices'] : array();
    $cleanZoneDevices = array();
    foreach ($zoneDevices as $zoneDevice) {
        $zoneDevice = (string)$zoneDevice;
        if (isset($zoneAcChoices[$zoneDevice]) && !isset($assignedAcDevices[$zoneDevice])) {
            $cleanZoneDevices[] = $zoneDevice;
            $assignedAcDevices[$zoneDevice] = true;
        }
    }
    if ($zoneName !== '') $cleanLoadZones[$loadMeter] = array('name'=>$zoneName, 'devices'=>$cleanZoneDevices);
}
$loadZones = $cleanLoadZones;
$canEditChillerConfig = in_array(strtolower((string)($_SESSION['user_type'] ?? '')), array('admin','superadmin'), true);
$chillerDevices = array();
foreach ($chillerDvl as $serial => $device) {
    if (!is_array($device)) continue;
    $name = (string)($device['name'] ?? $serial);
    $model = (string)($device['model'] ?? '');
    $haystack = strtolower($serial . ' ' . $name . ' ' . $model);
    $typeAbbr = strtoupper(trim((string)($chillerDetail[$model]['abbr'] ?? '')));
    $group = 'other';
    if (in_array((string)$serial, $mainPowerMeters, true)) $group = 'tower';
    elseif ($typeAbbr === 'AC' && in_array((string)$serial, $selectedChillerDevices, true)) $group = 'chiller';
    elseif (preg_match('/condenser|\bcdp\b|\bcwp\b/', $haystack)) $group = 'condenser';
    elseif (preg_match('/chwp|chw.?pump|chilled.?water.?pump/', $haystack)) $group = 'chwp';
    elseif (preg_match('/btu|load/', $haystack) && in_array((string)$serial, $selectedLoadDevices, true)) $group = 'load';
    if ($group === 'tower') $name = 'Main Meter: ' . $name;
    if ($group === 'load' && isset($loadZones[(string)$serial]['name'])) $name = $loadZones[(string)$serial]['name'];
    $chillerDevices[$group][$serial] = array('name'=>$name,'model'=>$model,'mode'=>(string)($device['mode'] ?? ''),'abbr'=>$typeAbbr);
}
$chillerGroups = array(
    'tower'=>array('Main Power','fa-bolt'),
    'chiller'=>array('Chiller','fa-snowflake'),
    'chwp'=>array('Chilled Water Pump','fa-droplet'),
    'load'=>array('Cooling Load / BTU','fa-building'),
    'other'=>array('Other Equipment','fa-microchip'),
);
?>
