<script>
const acChoices=<?php echo json_encode($zoneAcChoices,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>;
const loadChoices=<?php echo json_encode($chillerLoadChoices,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>;
let loadZones=<?php echo json_encode($loadZones,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>;
const floorplanPointConfig=<?php echo json_encode($floorplanPoints,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>;
const floorplanLayoutConfig=<?php echo json_encode($floorplanLayouts,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>;
const canEditFloorplan=<?php echo $canEditChillerConfig?'true':'false';?>;
const dashboardTemplateActive=<?php echo json_encode((string)($chillerTemplateConfig['active']??'chiller_diagram'));?>;
const dashboardTemplateLabels=<?php echo json_encode($chillerTemplateConfig['labels']??array(),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);?>;
const zoneEscape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
function initCalculationTooltips(){
    const root=document.querySelector('.cd-wrap');
    if(!root||root.dataset.calcTooltipsReady==='1')return;
    root.dataset.calcTooltipsReady='1';
    const tooltip=document.createElement('div');
    tooltip.className='cd-calc-tooltip';
    tooltip.setAttribute('role','tooltip');
    document.body.appendChild(tooltip);
    let active=null;
    const position=()=>{
        if(!active)return;
        const rect=active.getBoundingClientRect(),tip=tooltip.getBoundingClientRect(),gap=9;
        let left=rect.left+(rect.width-tip.width)/2;
        left=Math.max(12,Math.min(left,window.innerWidth-tip.width-12));
        let top=rect.top-tip.height-gap;
        if(top<8)top=rect.bottom+gap;
        tooltip.style.left=left+'px';
        tooltip.style.top=top+'px';
    };
    const show=target=>{
        const text=target?.dataset?.calcTooltip;
        if(!text)return;
        active=target;
        tooltip.textContent=text;
        tooltip.classList.add('is-visible');
        position();
    };
    const hide=()=>{active=null;tooltip.classList.remove('is-visible')};
    root.addEventListener('mouseover',event=>{const target=event.target.closest('[data-calc-tooltip]');if(target&&root.contains(target))show(target)});
    root.addEventListener('mouseout',event=>{const target=event.target.closest('[data-calc-tooltip]');if(target&&!target.contains(event.relatedTarget))hide()});
    root.addEventListener('focusin',event=>{const target=event.target.closest('[data-calc-tooltip]');if(target)show(target)});
    root.addEventListener('focusout',event=>{const target=event.target.closest('[data-calc-tooltip]');if(target&&!target.contains(event.relatedTarget))hide()});
    window.addEventListener('resize',position);
    window.addEventListener('scroll',position,true);
}
initCalculationTooltips();
function selectedLoadMeters(){return Array.from(document.querySelectorAll('[data-inline-load]:checked')).map(input=>input.value)}
function syncLoadZones(){document.querySelectorAll('[data-load-zone]').forEach(card=>{const meter=card.dataset.loadZone;loadZones[meter]={name:(card.querySelector('[data-load-zone-name]')?.value||loadChoices[meter]||meter).trim(),devices:Array.from(card.querySelectorAll('[data-load-zone-device]:checked')).map(input=>input.value)}})}
