const escapeHtml=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
const preferred=['status','mode','run','p_t','power','kw','current_btu','btu','ton','tons','temp','temp_entering','temp_leaving','chs_temp','chr_temp','water_flow','flow','sp','frequency','hz'];
const mainMeterFields = [['p_t','Power','kW'],['f','Frequency','Hz'],['e_p','Energy','kWh'],['pf_t','Power Factor','']];
function hasReadingError(data){
    const raw=data?.error;
    if(raw===undefined||raw===null||String(raw).trim()==='')return false;
    return Number(raw)!==0;
}
function chillerComStatus(data){
    const statuses = ['com_1a_status','com_2a_status'].map((key,index)=>{
        const raw=data?.[key];
        const state=raw===null||raw===undefined||String(raw).trim()===''?NaN:Number(raw);
        const text=state===1?'Running':state===0?'Stop':'--';
        const color=state===1?'#5df0b1':state===0?'#ff8585':'#8faac3';
        return '<div class="cd-value" title="'+key+'"><small>COM'+(index+1)+'</small><strong style="color:'+color+'">'+text+'</strong></div>';
    }).join('');
    const metrics = [['rla1','COM1 RLA','%'],['rla2','COM2 RLA','%'],['p_out1','COM1 kW','kW'],['p_out2','COM2 kW','kW'],['oil_pressure_1a','COM1 Oil Pressure','kPa'],['oil_pressure_2a','COM2 Oil Pressure','kPa']];
    return statuses + metrics.map(([key,label,unit])=>{
        const raw=data?.[key];
        const available=raw!==null&&raw!==undefined&&String(raw).trim()!==''&&Number.isFinite(Number(raw));
        const text=available?Number(raw).toFixed(2)+' '+unit:'--';
        return '<div class="cd-value" title="'+key+'"><small>'+label+'</small><strong>'+escapeHtml(text)+'</strong></div>';
    }).join('');
}
function renderMainMeter(values, data, readings){
    const card=values.closest('[data-cd-device]');
    const meterId=card?.dataset?.cdDevice||'',meterName=card?.querySelector('.cd-device-title b')?.textContent||'';
    const meterUnit=(meterName.match(/AMCC\D*0*(\d+)/i)||[])[1]||'';
    const hasConfiguredRelation=Object.keys(chillerMeterRelation||{}).length>0;
    const chillers=Array.from(document.querySelectorAll('[data-group="chiller"] [data-cd-device]')).filter(chillerCard=>{
        const id=chillerCard.dataset.cdDevice,name=chillerCard.querySelector('.cd-device-title b')?.textContent||'';
        if(hasConfiguredRelation)return Array.isArray(chillerMeterRelation?.[id])&&chillerMeterRelation[id].includes(meterId);
        const chillerUnit=(name.match(/ACH\D*0*(\d+)/i)||[])[1]||'';
        return !!meterUnit&&meterUnit===chillerUnit;
    }).map(chillerCard=>chillerCard.dataset.cdDevice);
    const pumps=Array.from(document.querySelectorAll('[data-group="chwp"] [data-cd-device]')).map(card=>card.dataset.cdDevice);
    const runningChillers=chillers.filter(id=>[readings?.[id]?.com_1a_status,readings?.[id]?.com_2a_status].some(state=>Number(state)===1)).length;
    const runningPumps=pumps.filter(id=>{const status=value(readings?.[id],['chwp_status','status','run','mode']);return Number(status)===1||Number(status)===2||/run|on|start/i.test(String(status??''))}).length;
    const active=runningChillers>0,badge=card?.querySelector('.cd-device-title span');
    card?.classList.toggle('is-running',active);
    if(badge)badge.textContent=active?'RUNNING':'--';
    const meterValues=mainMeterFields.map(([key,label,unit])=>{
        const raw=key==='pf_t'?(data?.pf_t??data?.pf??data?.power_factor):data?.[key];
        const available=raw!==null&&raw!==undefined&&String(raw).trim()!==''&&Number.isFinite(Number(raw));
        return '<div class="cd-value" title="'+key+'"><small>'+label+'</small><strong>'+escapeHtml(available?String(raw)+(unit?' '+unit:''):'--')+'</strong></div>';
    }).join('');
    const relation='Related Chiller ('+(hasConfiguredRelation?'Config':'Auto: ACH number = AMCC number')+'): ACH '+runningChillers+' / '+chillers.length+' running; CHWP '+runningPumps+' / '+pumps.length+' running.';
    values.innerHTML=meterValues+'<div class="cd-value" tabindex="0" title="'+relation+'" data-calc-tooltip="'+relation+'"><small>Relation</small><strong>ACH '+runningChillers+'/'+chillers.length+' · CHWP '+runningPumps+'/'+pumps.length+'</strong></div>';
}
function renderChwp(values,data,sn,readings){
    const vsdData=sn==='CHWP5101'?(readings?.VSD15101||{}):data;
    const configuredMeters=Array.isArray(chwpPowerMeterConfig?.[sn])?chwpPowerMeterConfig[sn]:[];
    const fallbackMeters=sn==='CHWP5101'&&!configuredMeters.length?['VSD15101']:[];
    const powerMeters=configuredMeters.length?configuredMeters:fallbackMeters;
    let power=null;
    if(powerMeters.length){let total=0,found=false;powerMeters.forEach(meter=>{const raw=value(readings?.[meter],['p_t','power','kw','active_power','motor_p']),numeric=Number(raw);if(Number.isFinite(numeric)){total+=numeric;found=true}});power=found?total:null}else power=value(data,['motor_p','p_t','power','kw','active_power']);
    const status=value(data,['chwp_status','status','run','mode']),frequency=value(vsdData,['motor_f','frequency','freq','f','hz']);
    let statusText='-',statusColor='#8faac3';
    if(status!==null){
        const numeric=Number(status);
        if(Number.isFinite(numeric)){
            statusText=numeric===0?'Stop':numeric===1||numeric===2?'Running':String(status);
            statusColor=numeric===0?'#ff8585':numeric===1||numeric===2?'#5df0b1':'#8faac3';
        }else{
            statusText=String(status);
            if(/run|on|start/i.test(statusText))statusColor='#5df0b1';
            else if(/stop|off/i.test(statusText))statusColor='#ff8585';
        }
    }
    const isRunning=statusText==='Running'||/run|on|start/i.test(statusText);
    const card=values.closest('[data-cd-device]'),badge=card?.querySelector('.cd-device-title span');
    card?.classList.toggle('is-running',isRunning);
    if(badge)badge.textContent=isRunning?'RUNNING':statusText==='Stop'?'STOP':'--';
    const display=(raw,unit)=>raw===null||raw===undefined||raw===''?'-':escapeHtml(String(raw)+(unit?' '+unit:''));
    const powerText=power===null||power===undefined||power===''?'-':Number.isFinite(Number(power))?Number(power).toFixed(3)+' kW':display(power,'kW');
    values.innerHTML='<div class="cd-value"><small>Status</small><strong style="color:'+statusColor+'">'+escapeHtml(statusText)+'</strong></div><div class="cd-value"><small>Frequency</small><strong>'+display(frequency,'Hz')+'</strong></div><div class="cd-value"><small>Power</small><strong>'+escapeHtml(powerText)+'</strong></div>';
}
const number=(data,keys)=>{for(const key of keys){const value=parseFloat(data?.[key]);if(Number.isFinite(value))return value}return 0};
const value=(data,keys)=>{for(const key of keys)if(data?.[key]!==undefined&&data[key]!==''&&data[key]!==null)return data[key];return null};
const buildingCode=(serial,prefix)=>{const normalized=String(serial||'').toUpperCase();return normalized.startsWith(prefix)?normalized.slice(prefix.length,prefix.length+2):''};
