const setPerf=(key,text)=>{const element=document.querySelector('[data-perf="'+key+'"]');if(element)element.textContent=text};
function calculateEnergyEfficiencyRatio(leavingTempC,enteringTempC,flowGpm,plantPowerKw){
    if(leavingTempC===null||leavingTempC===''||enteringTempC===null||enteringTempC===''||flowGpm===null||flowGpm===''||plantPowerKw===null||plantPowerKw==='')return null;
    const leaving=Number(leavingTempC),entering=Number(enteringTempC),flow=Number(flowGpm),power=Number(plantPowerKw);
    if(!Number.isFinite(leaving)||!Number.isFinite(entering)||!Number.isFinite(flow)||!Number.isFinite(power)||flow<0||power<=0)return null;
    const deltaF=Math.abs(leaving-entering)*1.8;
    return (500*deltaF*flow)/(power*1000);
}
function calculateCoefficientOfPerformance(coolingLoadTons,plantPowerKw){
    if(coolingLoadTons===null||coolingLoadTons===''||plantPowerKw===null||plantPowerKw==='')return null;
    const load=Number(coolingLoadTons),power=Number(plantPowerKw);
    if(!Number.isFinite(load)||!Number.isFinite(power)||load<0||power<=0)return null;
    const coolingCapacityKw=load*3.517;
    return coolingCapacityKw/power;
}
